text:
Componente para Next.js que detecta el final del hero con `IntersectionObserver`; evita listeners de `scroll` y solo renderiza cuando cambia de estado.

```tsx
// components/site-navbar.tsx
"use client";

import Link from "next/link";
import { useEffect, useState } from "react";

const links = [
  { href: "#proyectos", label: "Proyectos" },
  { href: "#metodo", label: "Método" },
  { href: "#contacto", label: "Contacto" },
];

type SiteNavbarProps = {
  heroId?: string;
};

export function SiteNavbar({ heroId = "hero" }: SiteNavbarProps) {
  const [pastHero, setPastHero] = useState(false);

  useEffect(() => {
    const hero = document.getElementById(heroId);

    if (!hero) {
      setPastHero(true);
      return;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        setPastHero(
          !entry.isIntersecting && entry.boundingClientRect.bottom <= 72,
        );
      },
      {
        // Coincide con la altura h-[72px] del navbar.
        rootMargin: "-72px 0px 0px",
        threshold: 0,
      },
    );

    observer.observe(hero);

    return () => observer.disconnect();
  }, [heroId]);

  return (
    <header
      data-past-hero={pastHero}
      className={[
        "fixed inset-x-0 top-0 z-50 h-[72px]",
        "border-b border-transparent",
        "transition-[background-color,box-shadow,border-color] duration-300 ease-out",
        "data-[past-hero=true]:border-white/10",
        "data-[past-hero=true]:bg-neutral-950/95",
        "data-[past-hero=true]:shadow-[0_12px_40px_rgba(0,0,0,0.22)]",
        "motion-reduce:transition-none",
      ].join(" ")}
    >
      <nav
        aria-label="Navegación principal"
        className="mx-auto flex h-full max-w-7xl items-center justify-between px-5 md:px-8"
      >
        <Link
          href="/"
          aria-label="Ir al inicio"
          className="flex min-h-11 items-center font-semibold tracking-[-0.03em] text-white outline-none focus-visible:ring-2 focus-visible:ring-white focus-visible:ring-offset-4 focus-visible:ring-offset-neutral-950"
        >
          Estudio
        </Link>

        <ul className="flex items-center gap-1">
          {links.map((link) => (
            <li key={link.href}>
              <Link
                href={link.href}
                className="flex min-h-11 items-center rounded-full px-4 text-sm text-white/75 transition-colors duration-200 hover:text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white"
              >
                {link.label}
              </Link>
            </li>
          ))}
        </ul>
      </nav>
    </header>
  );
}
```

El hero necesita el identificador correspondiente:

```tsx
<section id="hero" className="min-h-svh">
  {/* Hero */}
</section>
```

La transición ocurre cuando el borde inferior del hero pasa por debajo del navbar de `72px`, no simplemente cuando el hero deja de ocupar toda la pantalla. Además, si una ruta no tiene hero, el navbar adopta directamente su superficie sólida.
